import{_ as a,o as t,c as e,ag as o}from"./chunks/framework.DXGyWiRo.js";const g=JSON.parse('{"title":"Пользовательское соглашение","description":"","frontmatter":{},"headers":[],"relativePath":"user-agreement.md","filePath":"user-agreement.md","lastUpdated":null}'),l={name:"user-agreement.md"};function s(i,r,n,p,h,d){return t(),e("div",null,[...r[0]||(r[0]=[o('<h1 id="пользовательское-соглашение" tabindex="-1">Пользовательское соглашение <a class="header-anchor" href="#пользовательское-соглашение" aria-label="Permalink to &quot;Пользовательское соглашение&quot;">​</a></h1><p><strong>ИП Ульянов Алексей Владимирович</strong><br> ОГРНИП 321132600016985<br> Email: <a href="mailto:support@gosms.ru" target="_blank" rel="noreferrer">support@gosms.ru</a></p><p><em>Редакция от 21 апреля 2026 г.</em></p><hr><p>Настоящее Пользовательское соглашение (далее — <strong>Соглашение</strong>) регулирует порядок использования веб-кабинета и API сервиса GoSMS (далее — <strong>Сервис</strong>), расположенных на сайте <a href="https://gosms.ru" target="_blank" rel="noreferrer">gosms.ru</a>, и заключается между <strong>ИП Ульяновым Алексеем Владимировичем</strong> (далее — <strong>Администрация</strong>) и любым физическим или юридическим лицом, получившим доступ к Сервису (далее — <strong>Пользователь</strong>).</p><p>Использование Сервиса означает полное и безоговорочное принятие условий настоящего Соглашения.</p><h2 id="_1-основные-понятия" tabindex="-1">1. Основные понятия <a class="header-anchor" href="#_1-основные-понятия" aria-label="Permalink to &quot;1. Основные понятия&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Термин</th><th>Определение</th></tr></thead><tbody><tr><td><strong>Сервис</strong></td><td>Программный комплекс GoSMS для автоматизированного управления Android-устройствами, включая веб-кабинет, API и сопутствующую инфраструктуру</td></tr><tr><td><strong>Веб-кабинет</strong></td><td>Личный кабинет Пользователя на gosms.ru</td></tr><tr><td><strong>API</strong></td><td>Программный интерфейс для интеграции внешних систем с GoSMS</td></tr><tr><td><strong>Устройство</strong></td><td>Android-смартфон, подключённый к Сервису через приложение GoSMS Client</td></tr><tr><td><strong>SMS-сообщение</strong></td><td>Текстовое сообщение, отправляемое или принимаемое через SIM-карту Устройства</td></tr><tr><td><strong>API-ключ</strong></td><td>Уникальный идентификатор для авторизации запросов к API</td></tr></tbody></table><h2 id="_2-статус-сервиса" tabindex="-1">2. Статус Сервиса <a class="header-anchor" href="#_2-статус-сервиса" aria-label="Permalink to &quot;2. Статус Сервиса&quot;">​</a></h2><p>2.1. <strong>GoSMS не является SMS-шлюзом и не является оператором связи.</strong> Сервис предоставляет техническое решение для удалённого управления Android-устройствами Пользователя: отправки и приёма SMS-сообщений, просмотра журналов, управления контактами и интеграции через API.</p><p>2.2. Все SMS-сообщения отправляются непосредственно SIM-картой, установленной в Устройстве Пользователя. Отправителем сообщений является Пользователь, а не Администрация. Тарификация за отправку SMS осуществляется мобильным оператором Пользователя в соответствии с его тарифным планом.</p><p>2.3. Администрация не осуществляет предварительную модерацию содержимого сообщений.</p><h2 id="_3-регистрация-и-учетная-запись" tabindex="-1">3. Регистрация и учётная запись <a class="header-anchor" href="#_3-регистрация-и-учетная-запись" aria-label="Permalink to &quot;3. Регистрация и учётная запись&quot;">​</a></h2><p>3.1. Для использования Сервиса Пользователь обязан пройти регистрацию, указав действительный адрес электронной почты и иные запрашиваемые данные.</p><p>3.2. Пользователь обязан предоставлять достоверную и актуальную информацию при регистрации и обновлять её при изменении.</p><p>3.3. Пользователь несёт единоличную ответственность за сохранность учётных данных (логина, пароля, API-ключей). Администрация не несёт ответственности за ущерб, причинённый в результате несанкционированного использования учётной записи Пользователя.</p><p>3.4. При обнаружении несанкционированного доступа к учётной записи Пользователь обязан незамедлительно уведомить Администрацию по адресу <a href="mailto:support@gosms.ru" target="_blank" rel="noreferrer">support@gosms.ru</a> и сменить пароль.</p><p>3.5. Рекомендуется использовать двухфакторную аутентификацию (2FA) для защиты учётной записи.</p><h2 id="_4-права-и-обязанности-пользователя" tabindex="-1">4. Права и обязанности Пользователя <a class="header-anchor" href="#_4-права-и-обязанности-пользователя" aria-label="Permalink to &quot;4. Права и обязанности Пользователя&quot;">​</a></h2><h3 id="_4-1-пользователь-вправе" tabindex="-1">4.1. Пользователь вправе: <a class="header-anchor" href="#_4-1-пользователь-вправе" aria-label="Permalink to &quot;4.1. Пользователь вправе:&quot;">​</a></h3><ul><li>Использовать Сервис в соответствии с его назначением и выбранным тарифным планом.</li><li>Создавать и управлять API-ключами.</li><li>Подключать Android-устройства к Сервису.</li><li>Просматривать журналы сообщений и статистику.</li><li>Обращаться в техническую поддержку.</li><li>В любое время прекратить использование Сервиса.</li></ul><h3 id="_4-2-пользователь-обязан" tabindex="-1">4.2. Пользователь обязан: <a class="header-anchor" href="#_4-2-пользователь-обязан" aria-label="Permalink to &quot;4.2. Пользователь обязан:&quot;">​</a></h3><ul><li>Соблюдать настоящее Соглашение, <a href="/public-offer">Публичную оферту</a> и <a href="/aup">Правила допустимого использования</a>.</li><li>Использовать Сервис исключительно в законных целях и в соответствии с законодательством Российской Федерации.</li><li>Самостоятельно получать необходимые согласия получателей SMS-сообщений в соответствии с требованиями ФЗ-38 «О рекламе» и ФЗ-149 «Об информации».</li><li>Не использовать Сервис для рассылки спама, незаконного контента и иных нарушений <a href="/aup">Правил допустимого использования</a>.</li><li>Не предпринимать попыток получить несанкционированный доступ к Сервису или данным других пользователей.</li><li>Не использовать автоматизированные средства для работы с веб-кабинетом (парсинг), не предусмотренные официальным API.</li></ul><h2 id="_5-ответственность-за-содержание-сообщении" tabindex="-1">5. Ответственность за содержание сообщений <a class="header-anchor" href="#_5-ответственность-за-содержание-сообщении" aria-label="Permalink to &quot;5. Ответственность за содержание сообщений&quot;">​</a></h2><p>5.1. Пользователь несёт <strong>полную и единоличную ответственность</strong> за содержание всех SMS-сообщений, отправленных через Сервис, а также за соответствие их требованиям:</p><ul><li>ФЗ-38 «О рекламе» (в том числе ст. 18 — наличие согласия на рекламные рассылки);</li><li>ФЗ-149 «Об информации, информационных технологиях и о защите информации»;</li><li>иным применимым нормам законодательства РФ.</li></ul><p>5.2. Администрация вправе удалить сообщения или приостановить доступ к Сервису при наличии обоснованных подозрений в нарушении применимого законодательства или настоящего Соглашения.</p><h2 id="_6-доступность-сервиса" tabindex="-1">6. Доступность Сервиса <a class="header-anchor" href="#_6-доступность-сервиса" aria-label="Permalink to &quot;6. Доступность Сервиса&quot;">​</a></h2><p>6.1. Администрация прилагает разумные усилия для обеспечения работоспособности Сервиса, однако не гарантирует его непрерывную работу.</p><p>6.2. Администрация уведомляет Пользователей о плановых технических работах не менее чем за 24 часа через веб-кабинет или по электронной почте.</p><p>6.3. Администрация не несёт ответственности за недоступность Сервиса, вызванную:</p><ul><li>действиями или бездействием мобильных операторов;</li><li>неисправностью Устройства Пользователя;</li><li>сбоями сторонних сервисов и инфраструктуры;</li><li>обстоятельствами непреодолимой силы.</li></ul><h2 id="_7-ограничение-ответственности" tabindex="-1">7. Ограничение ответственности <a class="header-anchor" href="#_7-ограничение-ответственности" aria-label="Permalink to &quot;7. Ограничение ответственности&quot;">​</a></h2><p>7.1. Сервис предоставляется «как есть» (as is). Администрация не даёт гарантий его пригодности для каких-либо конкретных целей.</p><p>7.2. В максимальной степени, допускаемой применимым законодательством, Администрация не несёт ответственности за косвенные, случайные, специальные или штрафные убытки Пользователя.</p><p>7.3. Совокупная ответственность Администрации ограничена суммой, уплаченной Пользователем за последние 3 (три) месяца.</p><h2 id="_8-изменение-соглашения" tabindex="-1">8. Изменение Соглашения <a class="header-anchor" href="#_8-изменение-соглашения" aria-label="Permalink to &quot;8. Изменение Соглашения&quot;">​</a></h2><p>8.1. Администрация вправе изменять условия Соглашения. Новая редакция публикуется на <a href="https://legal.gosms.ru/user-agreement" target="_blank" rel="noreferrer">legal.gosms.ru/user-agreement</a> и вступает в силу через <strong>15 календарных дней</strong> с момента публикации.</p><p>8.2. Уведомление об изменении Соглашения направляется Пользователю по электронной почте, указанной при регистрации.</p><p>8.3. Продолжение использования Сервиса после вступления в силу изменений означает согласие с новой редакцией. Если Пользователь не согласен — он вправе расторгнуть договор, направив уведомление на <a href="mailto:support@gosms.ru" target="_blank" rel="noreferrer">support@gosms.ru</a>.</p><h2 id="_9-обработка-персональных-данных" tabindex="-1">9. Обработка персональных данных <a class="header-anchor" href="#_9-обработка-персональных-данных" aria-label="Permalink to &quot;9. Обработка персональных данных&quot;">​</a></h2><p>9.1. Администрация обрабатывает персональные данные Пользователя в соответствии с <a href="/privacy-policy">Политикой конфиденциальности</a> и требованиями ФЗ-152 «О персональных данных».</p><h2 id="_10-применимое-право-и-разрешение-споров" tabindex="-1">10. Применимое право и разрешение споров <a class="header-anchor" href="#_10-применимое-право-и-разрешение-споров" aria-label="Permalink to &quot;10. Применимое право и разрешение споров&quot;">​</a></h2><p>10.1. Соглашение регулируется законодательством Российской Федерации.</p><p>10.2. Споры разрешаются путём переговоров. При недостижении соглашения — в судебном порядке по месту нахождения Администрации. По требованиям потребителей — в соответствии с правилами подсудности, установленными Законом РФ «О защите прав потребителей».</p><p>10.3. Обязательный досудебный порядок: претензия направляется на <a href="mailto:support@gosms.ru" target="_blank" rel="noreferrer">support@gosms.ru</a>, срок ответа — 30 (тридцать) календарных дней.</p><h2 id="_11-реквизиты-администрации" tabindex="-1">11. Реквизиты Администрации <a class="header-anchor" href="#_11-реквизиты-администрации" aria-label="Permalink to &quot;11. Реквизиты Администрации&quot;">​</a></h2><p><strong>ИП Ульянов Алексей Владимирович</strong><br> ОГРНИП 321132600016985<br> Email: <a href="mailto:support@gosms.ru" target="_blank" rel="noreferrer">support@gosms.ru</a><br> Сайт: <a href="https://gosms.ru" target="_blank" rel="noreferrer">https://gosms.ru</a></p>',48)])])}const m=a(l,[["render",s]]);export{g as __pageData,m as default};
